import{_ as t}from"./chunks/files.B17OUyrr.js";import{_ as o,c as a,o as i,a2 as r}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Meet qDiff","description":"A short introduction to comparing files, folders and projects with qDiff on your Mac.","frontmatter":{"title":"Meet qDiff","description":"A short introduction to comparing files, folders and projects with qDiff on your Mac."},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1793948370000}'),n={name:"guide/introduction.md"};function s(h,e,l,d,c,f){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="meet-qdiff" tabindex="-1">Meet qDiff <a class="header-anchor" href="#meet-qdiff" aria-label="Permalink to &quot;Meet qDiff&quot;">​</a></h1><p>qDiff answers one question: <strong>what changed?</strong> Put two versions next to each other and everything different is marked in colour, so you can stop comparing line by line with your eyes.</p><img src="'+t+'" alt="Two files compared side by side" class="guide-shot"><h2 id="three-things-people-use-it-for" tabindex="-1">Three things people use it for <a class="header-anchor" href="#three-things-people-use-it-for" aria-label="Permalink to &quot;Three things people use it for&quot;">​</a></h2><ul><li><strong>Two files</strong> — a draft and its revision, a config before and after, two exports from the same tool. Changed words are highlighted inside the line.</li><li><strong>Two folders</strong> — a working folder and its backup. New, changed and missing files are easy to pick out, and you can bring the two sides back in sync.</li><li><strong>A project folder</strong> — everything you touched, gathered in one list. Read each change and commit without switching windows.</li></ul><p>Pictures, compressed archives and files that are not plain text are welcome too. <a href="./more.html">See more ways to compare</a>.</p><h2 id="start-in-three-steps" tabindex="-1">Start in three steps <a class="header-anchor" href="#start-in-three-steps" aria-label="Permalink to &quot;Start in three steps&quot;">​</a></h2><ol><li>Open qDiff and drag two files or folders onto the window — or choose them from the File menu.</li><li>Look at the coloured lines. Click the small map on the side, or use the previous / next buttons to walk through every change.</li><li>Edit, copy or sync what needs fixing. Save a picture of the comparison if someone else should see it.</li></ol><div class="tip custom-block"><p class="custom-block-title">No setup needed</p><p>There is no account to create and nothing to configure before the first comparison. Everything works offline.</p></div><h2 id="free-and-private" tabindex="-1">Free, and private <a class="header-anchor" href="#free-and-private" aria-label="Permalink to &quot;Free, and private&quot;">​</a></h2><p>Every comparison is available for free. The free version only shows a small mark in the tab bar; a one-time purchase removes it. qDiff reads only the files you choose and sends nothing anywhere — see the <a href="./../privacy/">Privacy Policy</a> for details.</p><h2 id="need-a-hand" tabindex="-1">Need a hand? <a class="header-anchor" href="#need-a-hand" aria-label="Permalink to &quot;Need a hand?&quot;">​</a></h2><p>The <a href="./faq.html">FAQ</a> covers the most common questions. If something still looks wrong, <a href="./../guide/support.html">write to us</a> and we will help.</p>',13)])])}const g=o(n,[["render",s]]);export{m as __pageData,g as default};
